-- OZ-004/PA-001: bind card identity hashing to trusted built-ins and atomically refresh document and D-1 proofs. PostgreSQL 17.
BEGIN;
SELECT finance_assert_document_definitions(pg_catalog.current_schema());
SELECT finance_assert_journal_use_definitions(pg_catalog.current_schema());
CREATE OR REPLACE FUNCTION finance_document_hash(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $de1a264$
 SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v::text,'UTF8')),'hex')
$de1a264$;
CREATE OR REPLACE FUNCTION finance_document_card_token(p_number text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $de1a264$
DECLARE n text;
BEGIN
 -- Deliberate ASCII space/hyphen normalization. Unknown/masked identifiers do not receive a token.
 n:=pg_catalog.replace(pg_catalog.replace(p_number,' ',''),'-','');
 IF n IS NULL OR n !~ '^[0-9]{12,19}$' THEN RETURN NULL; END IF;
 RETURN finance_document_hash(pg_catalog.jsonb_build_array('de1a-card-number-ascii-v1',n));
END $de1a264$;
CREATE OR REPLACE FUNCTION finance_assert_document_definitions(p_schema text) RETURNS jsonb LANGUAGE plpgsql AS $de1a264$
DECLARE expected jsonb := '{"version":"de1a-document-installation-v1-e257-e257-oz4-264-pa1","postgresMajor":17,"functions":[{"cost":"100","kind":"f","name":"finance_document_assert_request","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE q finance_document_requests%ROWTYPE; o finance_document_observations%ROWTYPE; d finance_document_registry%ROWTYPE;\n p jsonb; expected_payload jsonb; expected_result jsonb; ident jsonb; row_source record; x jsonb; previous finance_document_observations%ROWTYPE;\nBEGIN\n SELECT * INTO q FROM finance_document_requests WHERE request_id=p_request;\n SELECT * INTO o FROM finance_document_observations WHERE request_id=p_request;\n IF q.request_id IS NULL OR o.observation_id IS NULL THEN RAISE EXCEPTION ''Orphan document registration'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO d FROM finance_document_registry WHERE document_id=o.document_id;ident:=o.preview_json->''identity'';\n IF o.preview_json->>''previewHash'' IS DISTINCT FROM finance_document_hash(o.preview_json-''previewHash'')\n  OR o.preview_json->>''schemaVersion'' IS DISTINCT FROM ''de1a-document-preview-v1''\n  OR o.preview_json->>''canRegister'' IS DISTINCT FROM ''true'' OR o.preview_json->''issues'' IS DISTINCT FROM ''[]''::jsonb\n  OR o.preview_json->>''subjectId'' IS DISTINCT FROM o.subject_id OR o.preview_json->>''reviewRevisionId'' IS DISTINCT FROM o.review_revision_id\n  OR o.preview_json#>>''{source,kind}'' IS DISTINCT FROM o.source_kind OR o.preview_json#>>''{source,id}'' IS DISTINCT FROM o.source_id\n  OR o.preview_json->>''documentId'' IS DISTINCT FROM o.document_id OR (o.preview_json->>''version'')::integer IS DISTINCT FROM o.version-1\n  OR q.payload_hash IS DISTINCT FROM finance_document_hash(q.payload_json)\n  OR o.preview_json#>>''{observation,snapshotHash}'' IS DISTINCT FROM finance_document_hash(o.safe_snapshot_json)\n THEN RAISE EXCEPTION ''Document stored proof hash mismatch'' USING ERRCODE=''23514'';END IF;\n IF o.version>1 THEN\n  SELECT * INTO previous FROM finance_document_observations WHERE observation_id=o.previous_observation_id;\n  IF previous.document_id IS DISTINCT FROM o.document_id OR previous.version IS DISTINCT FROM o.version-1\n   THEN RAISE EXCEPTION ''Document observation chain mismatch'' USING ERRCODE=''23514'';END IF;\n END IF;\n expected_payload:=jsonb_build_object(''subjectId'',o.subject_id,''reviewRevisionId'',o.review_revision_id,''sourceKind'',o.source_kind,''sourceId'',o.source_id,\n  ''expectedPreviewHash'',o.preview_json->>''previewHash'',''expectedVersion'',o.version-1);\n expected_result:=jsonb_build_object(''documentId'',o.document_id,''portionId'',o.preview_json->>''portionId'',''observationId'',o.observation_id,''version'',o.version,''replayed'',false);\n IF q.actor_user_id<>o.actor_user_id OR q.payload_json IS DISTINCT FROM expected_payload OR q.result_json IS DISTINCT FROM expected_result\n  OR d.document_id IS NULL OR d.subject_id<>o.subject_id OR d.namespace IS DISTINCT FROM ident->>''namespace'' OR d.key_hash IS DISTINCT FROM ident->>''keyHash''\n  OR d.base_key_hash IS DISTINCT FROM ident->>''baseKeyHash'' OR d.descriptor_hash IS DISTINCT FROM ident->>''descriptorHash''\n  OR d.descriptor_json IS DISTINCT FROM o.safe_snapshot_json->''descriptor''\n  OR d.base_descriptor_json IS DISTINCT FROM NULLIF(o.safe_snapshot_json->''baseDescriptor'',''null''::jsonb)\n  OR d.descriptor_hash IS DISTINCT FROM finance_document_hash(d.descriptor_json)\n  OR d.base_key_hash IS DISTINCT FROM finance_document_hash(d.base_descriptor_json)\n  OR (o.version=1 AND (d.created_request_id<>o.request_id OR d.actor_user_id<>o.actor_user_id))\n THEN RAISE EXCEPTION ''Document request/owner agreement failed'' USING ERRCODE=''23514'';END IF;\n IF NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE document_id=d.document_id AND portion_id=o.preview_json->>''portionId'' AND locator=''whole''\n   AND request_id=d.created_request_id AND actor_user_id=d.actor_user_id)\n  OR (d.namespace=''mcm-card-approval-v1'' AND NOT EXISTS(SELECT 1 FROM finance_document_reservations WHERE document_id=d.document_id AND base_key_hash=d.base_key_hash AND base_descriptor_json=d.base_descriptor_json AND request_id=d.created_request_id AND actor_user_id=d.actor_user_id))\n  OR (d.namespace<>''mcm-card-approval-v1'' AND EXISTS(SELECT 1 FROM finance_document_reservations WHERE document_id=d.document_id))\n THEN RAISE EXCEPTION ''Document whole/reservation agreement failed'' USING ERRCODE=''23514'';END IF;\n FOR x IN SELECT value FROM jsonb_array_elements(o.preview_json#>''{observation,sources}'') LOOP\n  IF NOT EXISTS(SELECT 1 FROM finance_document_sources WHERE document_id=d.document_id AND source_kind=x->>''kind'' AND source_id=x->>''id'')\n   THEN RAISE EXCEPTION ''Document alias binding missing'' USING ERRCODE=''23514'';END IF;\n END LOOP;\n IF o.apply_xid=pg_current_xact_id_if_assigned() THEN\n  p:=finance_document_preview(o.subject_id,o.review_revision_id,o.source_kind,o.source_id);\n  IF (p-ARRAY[''version'',''previewHash'']) IS DISTINCT FROM (o.preview_json-ARRAY[''version'',''previewHash''])\n   THEN RAISE EXCEPTION ''Document sources changed during registration'' USING ERRCODE=''23514'';END IF;\n END IF;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_request text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_candidate","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\n<<document_preview>>\nDECLARE review_row record; r jsonb; selected jsonb; s jsonb; x jsonb; identity jsonb; observation jsonb; result jsonb;\n issues jsonb:=''[]''; aliases jsonb:=''[]''; sources jsonb:=''[]''; snapshots jsonb:=''[]''; company jsonb;\n full_descriptor jsonb; base_descriptor jsonb; safe_snapshot jsonb; current_counterparty text; unusable boolean:=false;\n key_hash text; base_hash text; descriptor_hash text; ns text; doc text; portion text; date_value text; official text; token text;\n basis text; other_basis text; active_apps integer:=0; candidate_count integer:=0; ver integer:=0; gross numeric; net numeric; tax numeric;\n actual_doc text; saved finance_document_registry%ROWTYPE;\nBEGIN\n IF p_kind NOT IN(''card'',''hometax'',''tax_invoice'') OR p_kind IS NULL OR finance_supply_id(to_jsonb(p_source)) IS DISTINCT FROM true\n  OR finance_supply_id(to_jsonb(p_subject)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(p_review_revision)) IS DISTINCT FROM true\n THEN RAISE EXCEPTION ''Invalid document selection'' USING ERRCODE=''22023''; END IF;\n SELECT v.*,c.subject_id AS case_subject INTO review_row FROM finance_supply_review_revisions v\n JOIN finance_supply_review_cases c USING(case_id) WHERE revision_id=p_review_revision;\n IF NOT FOUND OR review_row.case_subject<>p_subject OR review_row.state<>''recorded''\n  OR EXISTS(SELECT 1 FROM finance_supply_review_revisions WHERE case_id=review_row.case_id AND version>review_row.version)\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(review_row.payload_json->''members'') m WHERE m->>''kind''=p_kind AND m->>''sourceId''=p_source)\n THEN issues:=issues||finance_document_issue(''review_selection_unavailable'',''최신 기록판에 포함된 원천을 선택하세요.'');\n END IF;\n IF p_kind=''card'' THEN\n  SELECT to_jsonb(t) INTO selected FROM card_transactions t WHERE card_txn_id=p_source;\n  IF selected IS NOT NULL THEN\n   SELECT finance_document_card_token(card_num) INTO token FROM card_registry WHERE card_id=selected->>''card_id'';\n   date_value:=left(selected->>''approved_at'',10);\n   IF token IS NULL THEN issues:=issues||finance_document_issue(''card_identity_unavailable'',''카드 식별 근거를 확인하세요.''); END IF;\n   IF selected->>''approval_type'' IS DISTINCT FROM ''승인'' THEN issues:=issues||finance_document_issue(''card_type_unsupported'',''첫 등록은 유형이 확인된 승인 건만 지원합니다.''); END IF;\n   IF COALESCE(selected->>''approval_num'','''')='''' OR selected->>''approval_num'' !~ ''^[A-Za-z0-9-]+$''\n    OR selected->>''approved_at'' !~ ''^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$''\n   THEN issues:=issues||finance_document_issue(''card_approval_unavailable'',''승인번호와 초 단위 승인일시가 필요합니다.''); END IF;\n   net:=(selected->>''supply_amount'')::numeric;tax:=(selected->>''tax_amount'')::numeric;gross:=(selected->>''amount_total'')::numeric;\n   IF COALESCE((selected->>''service_charge'')::numeric,0)<>0 THEN issues:=issues||finance_document_issue(''card_service_unsupported'',''봉사료가 있는 승인은 별도 검토가 필요합니다.''); END IF;\n   IF selected#>>''{raw_json,CurrencyCode}'' IS DISTINCT FROM ''KRW'' THEN issues:=issues||finance_document_issue(''card_currency_unverified'',''원문 통화가 KRW로 확인된 승인만 등록할 수 있습니다.'');END IF;\n   ns:=''mcm-card-approval-v1'';base_descriptor:=jsonb_build_array(''de1a-card-base-v1'',token,selected->>''approval_num'',selected->>''approved_at'',''purchase'');base_hash:=finance_document_hash(base_descriptor);\n   key_hash:=finance_document_hash(jsonb_build_array(''de1a-card-full-v1'',base_hash,abs(gross)));\n   full_descriptor:=jsonb_build_array(ns,base_descriptor,gross);descriptor_hash:=finance_document_hash(full_descriptor);\n   SELECT count(*) INTO candidate_count FROM card_transactions t JOIN card_registry c USING(card_id)\n    WHERE finance_document_card_token(c.card_num)=token AND COALESCE(t.approval_num,'''')=COALESCE(selected->>''approval_num'','''')\n      AND t.approved_at=selected->>''approved_at'' AND t.approval_type=''승인'';\n   IF candidate_count<>1 THEN issues:=issues||finance_document_issue(''card_base_identity_conflict'',''같은 승인 기본키의 복수 원천을 확인하세요.''); END IF;\n   aliases:=jsonb_build_array(jsonb_build_object(''kind'',''card'',''row'',selected));\n  END IF;\n ELSE\n  IF p_kind=''hometax'' THEN SELECT to_jsonb(t) INTO selected FROM hometax_tax_invoices t WHERE hti_id=p_source;\n  ELSE SELECT to_jsonb(t) INTO selected FROM tax_invoices t WHERE invoice_id=p_source;END IF;\n  IF selected IS NOT NULL THEN\n   official:=btrim(selected->>''nts_send_key'');date_value:=selected->>''write_date'';\n   IF official IS NULL OR official='''' OR official !~ ''^[A-Za-z0-9-]+$'' THEN issues:=issues||finance_document_issue(''official_key_unavailable'',''공식 승인번호를 확인하세요.''); END IF;\n   net:=(selected->>''amount_total'')::numeric;tax:=(selected->>''tax_total'')::numeric;gross:=(selected->>''total_amount'')::numeric;\n   ns:=''kr-nts-approval'';key_hash:=finance_document_hash(jsonb_build_array(ns,official));\n   full_descriptor:=jsonb_build_array(ns,official);descriptor_hash:=finance_document_hash(full_descriptor);\n   SELECT COALESCE(jsonb_agg(a ORDER BY a->>''kind'',a->''row''->>''hti_id'',a->''row''->>''invoice_id''),''[]'') INTO aliases FROM (\n    SELECT jsonb_build_object(''kind'',''hometax'',''row'',to_jsonb(t)) a FROM hometax_tax_invoices t WHERE btrim(t.nts_send_key)=official\n    UNION ALL SELECT jsonb_build_object(''kind'',''tax_invoice'',''row'',to_jsonb(t)) FROM tax_invoices t WHERE btrim(t.nts_send_key)=official\n   ) all_aliases;\n  END IF;\n END IF;\n IF selected IS NULL THEN issues:=issues||finance_document_issue(''source_missing'',''선택한 원천을 찾을 수 없습니다.'');\n ELSE\n  IF net IS NULL OR tax IS NULL OR gross IS NULL OR net<0 OR tax<0 OR gross<=0 OR net+tax<>gross\n   OR greatest(abs(net),abs(tax),abs(gross))>9007199254740991 OR net<>trunc(net) OR tax<>trunc(tax) OR gross<>trunc(gross)\n  THEN issues:=issues||finance_document_issue(''amount_unsupported'',''원 단위 양수 전체 금액을 확인하세요.'');unusable:=true; END IF;\n  company:=finance_document_subject(p_subject,date_value);\n  IF company IS NULL THEN issues:=issues||finance_document_issue(''subject_unresolved'',''업무일의 단일 회사 기준을 확인하세요.'');unusable:=true; END IF;\n  IF vat_followup_date(date_value) IS DISTINCT FROM true OR (p_kind=''card'' AND token IS NULL) THEN unusable:=true;END IF;\n  FOR x IN SELECT value FROM jsonb_array_elements(aliases) LOOP\n   r:=x->''row'';\n   IF x->>''kind''=''card'' THEN\n    s:=jsonb_build_object(''kind'',''card'',''id'',r->>''card_txn_id'',''date'',date_value,''direction'',''purchase'',''cardToken'',token,\n     ''approvalType'',r->''approval_type'',''approvalNumber'',r->''approval_num'',''approvedAt'',r->''approved_at'',''supply'',r->''supply_amount'',''tax'',r->''tax_amount'',''total'',r->''amount_total'',\n     ''serviceCharge'',r->''service_charge'',''storeCorpNum'',r->''store_corp_num'',''storeTaxType'',r->''store_tax_type'',''excluded'',r->''excluded'',\n     ''observationState'',r->''is_purchased'',''currency'',r#>''{raw_json,CurrencyCode}'',\n     ''historyKeyHash'',finance_document_hash(r->''history_key''),''dedupKeyHash'',finance_document_hash(r->''dedup_key''),''rawHash'',finance_document_hash(r->''raw_json''));\n   ELSE\n    s:=jsonb_build_object(''kind'',x->>''kind'',''id'',COALESCE(r->>''hti_id'',r->>''invoice_id''),''date'',r->''write_date'',''direction'',r->''direction'',\n     ''approvalNumber'',btrim(r->>''nts_send_key''),''supply'',r->''amount_total'',''tax'',r->''tax_total'',''total'',r->''total_amount'',''taxType'',r->''tax_type'',\n     ''modifyCode'',r->''modify_code'',''supplier'',r->''invoicer_corp_num'',''supplierName'',r->''invoicer_corp_name'',''recipient'',r->''invoicee_corp_num'',''recipientName'',r->''invoicee_corp_name'',''excluded'',r->''excluded'',''cancelledAt'',r->''canceled_at'',\n     ''sendState'',r->''nts_send_state'',''originalInvoiceId'',r->''original_invoice_id'',''rawWriteDate'',r#>''{raw_json,WriteDate}'',\n     ''originalApprovalNumber'',r#>''{raw_json,OriginalNTSConfirmNum}'',''originalNtsSendKey'',r#>''{raw_json,OriginalNTSSendKey}'',\n     ''lineItemsHash'',finance_document_hash(r->''line_items''),''rawHash'',finance_document_hash(r->''raw_json''));\n    current_counterparty:=CASE r->>''direction'' WHEN ''purchase'' THEN r->>''invoicer_corp_num'' WHEN ''sales'' THEN r->>''invoicee_corp_num'' END;\n    IF current_counterparty IS NULL OR current_counterparty !~ ''^[0-9]{10}$'' THEN issues:=issues||finance_document_issue(''invoice_counterparty_unverified'',''문서 방향과 거래처 번호를 확인하세요.'');END IF;\n    other_basis:=finance_document_hash(jsonb_build_array(r->''write_date'',r->''direction'',r->''amount_total'',r->''tax_total'',r->''total_amount'',r->''tax_type'',COALESCE(r->>''modify_code'',''''),current_counterparty));\n    IF basis IS NOT NULL AND basis<>other_basis THEN issues:=issues||finance_document_issue(''official_invoice_content_conflict'',''같은 승인번호의 문서 내용이 서로 다릅니다.''); END IF;basis:=other_basis;\n    IF x->>''kind''=''tax_invoice'' AND r->>''canceled_at'' IS NULL AND COALESCE((r->>''nts_send_state'')::integer,0)=4 THEN active_apps:=active_apps+1;END IF;\n    IF x->>''kind''=''hometax'' AND (COALESCE(r#>>''{raw_json,WriteDate}'','''') !~ ''^[0-9]{8}$'' OR r#>>''{raw_json,WriteDate}'' IS DISTINCT FROM replace(r->>''write_date'',''-'','''')) THEN issues:=issues||finance_document_issue(''source_date_unverified'',''원문 작성일과 저장 작성일이 일치하지 않습니다.'');END IF;\n    IF company IS NOT NULL AND x->>''kind''=''hometax'' AND (CASE r->>''direction'' WHEN ''purchase'' THEN r->>''invoicee_corp_num'' WHEN ''sales'' THEN r->>''invoicer_corp_num'' ELSE '''' END) IS DISTINCT FROM company->>''corpNum''\n     THEN issues:=issues||finance_document_issue(''source_subject_conflict'',''문서 주체와 선택한 회사가 다릅니다.'');END IF;\n   END IF;\n   IF COALESCE((r->>''excluded'')::integer,0)<>0 OR r->>''canceled_at'' IS NOT NULL THEN issues:=issues||finance_document_issue(''source_inactive'',''제외 또는 취소된 문서는 첫 등록에서 보류됩니다.'');END IF;\n   IF x->>''kind''=''tax_invoice'' AND COALESCE((r->>''nts_send_state'')::integer,0)<>4 THEN issues:=issues||finance_document_issue(''source_not_transmitted'',''공식 전송 완료 상태를 확인하세요.'');END IF;\n   IF COALESCE(r->>''modify_code'','''')<>'''' THEN issues:=issues||finance_document_issue(''correction_unsupported'',''수정 문서는 별도 계보 검토가 필요합니다.'');END IF;\n   snapshots:=snapshots||jsonb_build_array(s);\n   sources:=sources||jsonb_build_array(jsonb_build_object(''kind'',s->>''kind'',''id'',s->>''id'',''sourceHash'',finance_document_hash(s)));\n  END LOOP;\n  IF active_apps>1 THEN issues:=issues||finance_document_issue(''multiple_active_app_invoice_rows'',''같은 승인번호의 활성 앱 문서가 여러 개입니다.'');END IF;\n  doc:=''fdoc-''||key_hash;portion:=''fdp-''||key_hash;\n  SELECT d.* INTO saved FROM finance_document_registry d WHERE d.document_id=doc OR (d.namespace=ns AND d.key_hash=document_preview.key_hash) LIMIT 1;\n  IF FOUND AND (saved.subject_id<>p_subject OR saved.descriptor_hash<>descriptor_hash OR saved.base_key_hash IS DISTINCT FROM base_hash\n   OR saved.descriptor_json IS DISTINCT FROM full_descriptor OR saved.base_descriptor_json IS DISTINCT FROM base_descriptor)\n   THEN issues:=issues||finance_document_issue(''registered_identity_conflict'',''이미 등록한 문서의 식별 근거와 다릅니다.'');END IF;\n  IF base_hash IS NOT NULL AND EXISTS(SELECT 1 FROM finance_document_reservations q WHERE q.base_key_hash=base_hash AND q.document_id<>doc)\n   THEN issues:=issues||finance_document_issue(''card_base_identity_conflict'',''기존 승인 기본키의 문서와 금액 또는 원천이 다릅니다.'');END IF;\n  FOR x IN SELECT value FROM jsonb_array_elements(sources) LOOP\n   SELECT document_id INTO actual_doc FROM finance_document_sources WHERE source_kind=x->>''kind'' AND source_id=x->>''id'';\n   IF actual_doc IS NOT NULL AND actual_doc<>doc THEN issues:=issues||finance_document_issue(''source_identity_changed'',''원천이 기존 문서와 다른 식별자로 바뀌었습니다.'');END IF;\n  END LOOP;\n  SELECT COALESCE(max(version),0) INTO ver FROM finance_document_observations WHERE document_id=doc;\n  identity:=jsonb_build_object(''namespace'',ns,''keyHash'',key_hash,''baseKeyHash'',base_hash,''descriptorHash'',descriptor_hash);\n  safe_snapshot:=jsonb_build_object(''sourceSnapshots'',snapshots,''subject'',company,''reviewHash'',review_row.preview_hash,''descriptor'',full_descriptor,''baseDescriptor'',base_descriptor);\n  observation:=jsonb_build_object(''subjectRevisionId'',company->>''revisionId'',''date'',date_value,''direction'',CASE WHEN p_kind=''card'' THEN ''purchase'' ELSE selected->>''direction'' END,\n   ''approvalNumber'',CASE WHEN p_kind=''card'' THEN selected->>''approval_num'' ELSE official END,''supply'',net,''tax'',tax,''total'',gross,''sources'',sources,\n   ''snapshotHash'',finance_document_hash(safe_snapshot));\n END IF;\n IF unusable THEN identity:=NULL;observation:=NULL;doc:=NULL;portion:=NULL;ver:=0;END IF;\n result:=jsonb_build_object(''schemaVersion'',''de1a-document-preview-v1'',''subjectId'',p_subject,''reviewRevisionId'',p_review_revision,\n  ''source'',jsonb_build_object(''kind'',p_kind,''id'',p_source),''canRegister'',jsonb_array_length(issues)=0,''issues'',issues,''documentId'',doc,''portionId'',portion,''version'',ver,\n  ''identity'',identity,''observation'',observation);\n RETURN result||jsonb_build_object(''previewHash'',finance_document_hash(result),''_safeSnapshot'',safe_snapshot,''_descriptor'',full_descriptor,''_baseDescriptor'',base_descriptor);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject text, p_review_revision text, p_kind text, p_source text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_card_token","rows":"0","binary":null,"config":null,"result":"text","source":"\nDECLARE n text;\nBEGIN\n -- Deliberate ASCII space/hyphen normalization. Unknown/masked identifiers do not receive a token.\n n:=pg_catalog.replace(pg_catalog.replace(p_number,'' '',''''),''-'','''');\n IF n IS NULL OR n !~ ''^[0-9]{12,19}$'' THEN RETURN NULL; END IF;\n RETURN finance_document_hash(pg_catalog.jsonb_build_array(''de1a-card-number-ascii-v1'',n));\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_number text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_hash","rows":"0","binary":null,"config":null,"result":"text","source":"\n SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v::text,''UTF8'')),''hex'')\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_immutable","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN RAISE EXCEPTION ''Document registry history is immutable'' USING ERRCODE=''23514'';END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_insert_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE p jsonb; candidate jsonb; prev finance_document_observations%ROWTYPE;\nBEGIN\n PERFORM finance_document_write_lock();\n PERFORM finance_assert_document_definitions(current_schema());\n IF TG_TABLE_NAME=''finance_document_observations'' THEN\n  candidate:=finance_document_candidate(NEW.subject_id,NEW.review_revision_id,NEW.source_kind,NEW.source_id);\n  p:=candidate-ARRAY[''_safeSnapshot'',''_descriptor'',''_baseDescriptor''];\n  SELECT * INTO prev FROM finance_document_observations WHERE document_id=NEW.document_id ORDER BY version DESC LIMIT 1;\n  IF p->>''canRegister'' IS DISTINCT FROM ''true'' OR NEW.preview_json IS DISTINCT FROM p OR NEW.document_id IS DISTINCT FROM p->>''documentId''\n   OR NEW.version<>COALESCE(prev.version,0)+1 OR NEW.previous_observation_id IS DISTINCT FROM prev.observation_id\n   OR NEW.apply_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.safe_snapshot_json IS DISTINCT FROM candidate->''_safeSnapshot''\n  THEN RAISE EXCEPTION ''Document observation proof or version mismatch'' USING ERRCODE=''23514'';END IF;\n END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_issue","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\n SELECT jsonb_build_array(jsonb_build_object(''code'',p_code,''message'',p_message))\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p_code text, p_message text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_list","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE d finance_document_registry%ROWTYPE; o finance_document_observations%ROWTYPE; last_row finance_document_observations%ROWTYPE;\n docs jsonb:=''[]''; history jsonb:=''[]''; result jsonb; doc_count integer:=0; observation_count integer; previous_version integer; portion text;\nBEGIN\n PERFORM finance_assert_document_definitions(current_schema());\n IF finance_supply_id(to_jsonb(p_subject)) IS DISTINCT FROM true OR (p_document IS NOT NULL AND finance_supply_id(to_jsonb(p_document)) IS DISTINCT FROM true)\n  THEN RAISE EXCEPTION ''Invalid document list selection'' USING ERRCODE=''22023'';END IF;\n FOR d IN SELECT * FROM finance_document_registry WHERE subject_id=p_subject AND (p_document IS NULL OR document_id=p_document) ORDER BY created_at DESC,document_id DESC LIMIT 101 LOOP\n  doc_count:=doc_count+1;IF doc_count>100 THEN EXIT;END IF;observation_count:=0;previous_version:=0;\n  -- All history is validated before a capped projection is returned. Current source/subject changes do not invalidate an old registration.\n  FOR o IN SELECT * FROM finance_document_observations WHERE document_id=d.document_id ORDER BY version LOOP\n   PERFORM finance_document_assert_request(o.request_id);\n   IF o.version<>previous_version+1 THEN RAISE EXCEPTION ''Document observation history has a gap'' USING ERRCODE=''55000'';END IF;\n   previous_version:=o.version;observation_count:=observation_count+1;last_row:=o;\n  END LOOP;\n  IF observation_count=0 THEN RAISE EXCEPTION ''Document history is missing'' USING ERRCODE=''55000'';END IF;\n  SELECT portion_id INTO portion FROM finance_document_portions WHERE document_id=d.document_id AND locator=''whole'';\n  docs:=docs||jsonb_build_array(jsonb_build_object(''documentId'',d.document_id,''portionId'',portion,''version'',last_row.version,\n   ''latestObservation'',finance_document_summary(last_row.preview_json->''observation''),''observationCount'',observation_count));\n  IF p_document IS NOT NULL THEN\n   SELECT COALESCE(jsonb_agg(v ORDER BY version DESC),''[]'') INTO history FROM(\n    SELECT version,jsonb_build_object(''observationId'',observation_id,''version'',version,''reviewRevisionId'',review_revision_id,\n     ''createdAt'',created_at,''summary'',finance_document_summary(preview_json->''observation'')) v\n    FROM finance_document_observations WHERE document_id=d.document_id ORDER BY version DESC LIMIT 100) h;\n  END IF;\n END LOOP;\n result:=jsonb_build_object(''documents'',docs,''hasMore'',doc_count>100);\n IF p_document IS NOT NULL THEN result:=result||jsonb_build_object(''history'',history,''historyHasMore'',COALESCE(observation_count,0)>100);END IF;\n RETURN result;\nEXCEPTION WHEN invalid_parameter_value OR serialization_failure OR deadlock_detected THEN RAISE;\n WHEN OTHERS THEN RAISE EXCEPTION ''Document archive unavailable: %'',SQLERRM USING ERRCODE=''55000'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject text, p_document text DEFAULT NULL::text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_preview","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\n SELECT finance_document_candidate(p_subject,p_review_revision,p_kind,p_source)-ARRAY[''_safeSnapshot'',''_descriptor'',''_baseDescriptor'']\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p_subject text, p_review_revision text, p_kind text, p_source text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_register","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE p jsonb; candidate jsonb; payload jsonb; answer jsonb; old finance_document_requests%ROWTYPE; prev text; observation_id text; x jsonb;\nBEGIN\n PERFORM finance_document_write_lock();PERFORM finance_assert_document_definitions(current_schema());\n IF finance_supply_id(to_jsonb(p_request)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(p_actor)) IS DISTINCT FROM true\n  OR p_expected_version IS NULL OR p_expected_version<0 OR p_expected_hash IS NULL OR p_expected_hash !~ ''^[a-f0-9]{64}$''\n THEN RAISE EXCEPTION ''Invalid document registration request'' USING ERRCODE=''22023'';END IF;\n payload:=jsonb_build_object(''subjectId'',p_subject,''reviewRevisionId'',p_review_revision,''sourceKind'',p_kind,''sourceId'',p_source,''expectedPreviewHash'',p_expected_hash,''expectedVersion'',p_expected_version);\n SELECT * INTO old FROM finance_document_requests WHERE request_id=p_request;\n IF FOUND THEN\n  IF old.actor_user_id<>p_actor OR old.payload_json IS DISTINCT FROM payload OR old.payload_hash<>finance_document_hash(payload)\n   THEN RAISE EXCEPTION ''Document request conflict'' USING ERRCODE=''23514'';END IF;\n  PERFORM finance_document_assert_request(p_request);\n  RETURN old.result_json||jsonb_build_object(''replayed'',true);\n END IF;\n candidate:=finance_document_candidate(p_subject,p_review_revision,p_kind,p_source);p:=candidate-ARRAY[''_safeSnapshot'',''_descriptor'',''_baseDescriptor''];\n IF p->>''canRegister'' IS DISTINCT FROM ''true'' OR p->>''previewHash''<>p_expected_hash OR (p->>''version'')::integer<>p_expected_version\n  THEN RAISE EXCEPTION ''Document preview changed or selection is unresolved'' USING ERRCODE=''23514'';END IF;\n IF p_expected_version=0 THEN\n  INSERT INTO finance_document_registry(document_id,subject_id,namespace,key_hash,base_key_hash,descriptor_hash,descriptor_json,base_descriptor_json,created_request_id,actor_user_id)\n   VALUES(p->>''documentId'',p_subject,p#>>''{identity,namespace}'',p#>>''{identity,keyHash}'',p#>>''{identity,baseKeyHash}'',p#>>''{identity,descriptorHash}'',candidate->''_descriptor'',NULLIF(candidate->''_baseDescriptor'',''null''::jsonb),p_request,p_actor);\n  INSERT INTO finance_document_portions(portion_id,document_id,locator,request_id,actor_user_id) VALUES(p->>''portionId'',p->>''documentId'',''whole'',p_request,p_actor);\n  IF p#>>''{identity,baseKeyHash}'' IS NOT NULL THEN\n   INSERT INTO finance_document_reservations(namespace,base_key_hash,base_descriptor_json,document_id,request_id,actor_user_id)\n    VALUES(''mcm-card-approval-v1'',p#>>''{identity,baseKeyHash}'',candidate->''_baseDescriptor'',p->>''documentId'',p_request,p_actor);\n  END IF;\n END IF;\n FOR x IN SELECT value FROM jsonb_array_elements(p#>''{observation,sources}'') LOOP\n  IF NOT EXISTS(SELECT 1 FROM finance_document_sources WHERE source_kind=x->>''kind'' AND source_id=x->>''id'') THEN\n   INSERT INTO finance_document_sources(source_kind,source_id,document_id,request_id,actor_user_id) VALUES(x->>''kind'',x->>''id'',p->>''documentId'',p_request,p_actor);\n  END IF;\n END LOOP;\n SELECT o.observation_id INTO prev FROM finance_document_observations o WHERE document_id=p->>''documentId'' ORDER BY version DESC LIMIT 1;\n observation_id:=''fdo-''||gen_random_uuid()::text;\n INSERT INTO finance_document_observations(observation_id,document_id,version,previous_observation_id,subject_id,review_revision_id,source_kind,source_id,preview_json,safe_snapshot_json,request_id,actor_user_id)\n  VALUES(observation_id,p->>''documentId'',p_expected_version+1,prev,p_subject,p_review_revision,p_kind,p_source,p,candidate->''_safeSnapshot'',p_request,p_actor);\n answer:=jsonb_build_object(''documentId'',p->>''documentId'',''portionId'',p->>''portionId'',''observationId'',observation_id,''version'',p_expected_version+1,''replayed'',false);\n INSERT INTO finance_document_requests(request_id,actor_user_id,payload_json,payload_hash,result_json) VALUES(p_request,p_actor,payload,finance_document_hash(payload),answer);\n RETURN answer;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject text, p_review_revision text, p_kind text, p_source text, p_expected_hash text, p_expected_version integer, p_request text, p_actor text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text, text, text, text, text, integer, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_row_agreement","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE req text; d finance_document_registry%ROWTYPE; o finance_document_observations%ROWTYPE;\nBEGIN\n IF TG_TABLE_NAME=''finance_document_registry'' THEN req:=NEW.created_request_id;ELSE req:=NEW.request_id;END IF;\n PERFORM finance_document_assert_request(req);\n IF TG_TABLE_NAME IN(''finance_document_sources'',''finance_document_reservations'',''finance_document_portions'') THEN\n  SELECT * INTO o FROM finance_document_observations WHERE request_id=req;\n  IF NEW.document_id IS DISTINCT FROM o.document_id OR NEW.actor_user_id IS DISTINCT FROM o.actor_user_id THEN RAISE EXCEPTION ''Document subordinate owner mismatch'' USING ERRCODE=''23514'';END IF;\n  IF TG_TABLE_NAME=''finance_document_sources'' THEN\n   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(o.preview_json#>''{observation,sources}'') s WHERE s->>''kind''=NEW.source_kind AND s->>''id''=NEW.source_id)\n    THEN RAISE EXCEPTION ''Unexpected document alias binding'' USING ERRCODE=''23514'';END IF;\n  END IF;\n END IF;\n RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_subject","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE chosen jsonb; other jsonb; sid text;\nBEGIN\n IF vat_followup_date(p_date) IS DISTINCT FROM true THEN RETURN NULL; END IF;\n SELECT payload_json INTO chosen FROM vat_filing_subject_revisions\n WHERE subject_id=p_subject AND payload_json->>''effectiveFrom''<=p_date\n   AND (payload_json->>''effectiveTo'' IS NULL OR payload_json->>''effectiveTo''>=p_date) ORDER BY version DESC LIMIT 1;\n IF chosen IS NULL OR chosen->>''state'' IS DISTINCT FROM ''verified'' OR chosen->>''entityType'' IS DISTINCT FROM ''corporation''\n  OR chosen->>''vatRegime'' IS DISTINCT FROM ''general'' OR chosen->>''filingUnit'' IS DISTINCT FROM ''single_business_place''\n  OR COALESCE(chosen->>''corpNum'','''') !~ ''^[0-9]{10}$'' THEN RETURN NULL; END IF;\n IF EXISTS(SELECT 1 FROM vat_filing_subject_revisions r WHERE r.subject_id=p_subject AND r.version>(chosen->>''version'')::integer\n   AND r.payload_json->>''effectiveFrom''<=p_date AND r.payload_json->>''effectiveTo''<p_date\n   AND r.payload_json->>''effectiveFrom''<=COALESCE(chosen->>''effectiveTo'',''9999-12-31'')\n   AND chosen->>''effectiveFrom''<=r.payload_json->>''effectiveTo'') THEN RETURN NULL; END IF;\n FOR sid IN SELECT DISTINCT subject_id FROM vat_filing_subject_revisions WHERE subject_id<>p_subject LOOP\n  SELECT payload_json INTO other FROM vat_filing_subject_revisions\n   WHERE subject_id=sid AND payload_json->>''effectiveFrom''<=p_date\n    AND (payload_json->>''effectiveTo'' IS NULL OR payload_json->>''effectiveTo''>=p_date) ORDER BY version DESC LIMIT 1;\n  IF other IS NOT NULL AND other->>''corpNum''=chosen->>''corpNum'' AND NOT EXISTS(\n   SELECT 1 FROM vat_filing_subject_revisions r WHERE r.subject_id=sid AND r.version>(other->>''version'')::integer\n    AND r.payload_json->>''effectiveFrom''<=p_date AND r.payload_json->>''effectiveTo''<p_date\n    AND r.payload_json->>''effectiveFrom''<=COALESCE(other->>''effectiveTo'',''9999-12-31'')\n    AND other->>''effectiveFrom''<=r.payload_json->>''effectiveTo'') THEN RETURN NULL; END IF;\n END LOOP;\n RETURN chosen;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject text, p_date text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_summary","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\n SELECT jsonb_build_object(''date'',p->''date'',''direction'',p->''direction'',''approvalNumber'',p->''approvalNumber'',''supply'',p->''supply'',''tax'',p->''tax'',''total'',p->''total'')\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_document_write_lock","rows":"0","binary":null,"config":null,"result":"void","source":"\nBEGIN\n IF current_setting(''transaction_isolation'')<>''read committed'' THEN\n  RAISE EXCEPTION ''Document writes require READ COMMITTED for fresh source snapshots after locks'' USING ERRCODE=''23514'';\n END IF;\n PERFORM pg_advisory_xact_lock(1296256326,1);\n -- SHARE prevents source INSERT/UPDATE/DELETE while a registration is being validated, without installing old-table triggers.\n LOCK TABLE card_registry,card_transactions,hometax_tax_invoices,tax_invoices,vat_filing_subjects,vat_filing_subject_revisions,\n  finance_supply_review_cases,finance_supply_review_revisions IN SHARE MODE;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false}],"tables":["finance_document_observations","finance_document_portions","finance_document_registry","finance_document_requests","finance_document_reservations","finance_document_sources"],"strictRelations":["finance_document_observations","finance_document_portions","finance_document_registry","finance_document_requests","finance_document_reservations","finance_document_sources"],"installation":{"relations":[{"kind":"r","name":"finance_document_observations","policies":[],"rowSecurity":false,"forceRowSecurity":false},{"kind":"r","name":"finance_document_portions","policies":[],"rowSecurity":false,"forceRowSecurity":false},{"kind":"r","name":"finance_document_registry","policies":[],"rowSecurity":false,"forceRowSecurity":false},{"kind":"r","name":"finance_document_requests","policies":[],"rowSecurity":false,"forceRowSecurity":false},{"kind":"r","name":"finance_document_reservations","policies":[],"rowSecurity":false,"forceRowSecurity":false},{"kind":"r","name":"finance_document_sources","policies":[],"rowSecurity":false,"forceRowSecurity":false}],"structures":[{"name":"finance_document_observations","rules":[],"columns":[{"name":"observation_id","type":"text","default":null,"notNull":true,"identity":"","position":1,"collation":"pg_catalog.default","generated":""},{"name":"document_id","type":"text","default":null,"notNull":true,"ident