name":"finance_document_sources_document_id_fkey","type":"f","match":"s","target":"<self>.finance_document_registry","validated":true,"deferrable":false,"definition":"FOREIGN KEY (document_id) REFERENCES finance_document_registry(document_id)","targetKeys":[1],"deleteAction":"a","updateAction":"a","initiallyDeferred":false},{"keys":[1,2],"name":"finance_document_sources_pkey","type":"p","match":" ","target":null,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (source_kind, source_id)","targetKeys":null,"deleteAction":" ","updateAction":" ","initiallyDeferred":false},{"keys":[1],"name":"finance_document_sources_source_kind_check","type":"c","match":" ","target":null,"validated":true,"deferrable":false,"definition":"CHECK (source_kind = ANY (ARRAY[''card''::text, ''hometax''::text, ''tax_invoice''::text]))","targetKeys":null,"deleteAction":" ","updateAction":" ","initiallyDeferred":false},{"keys":null,"name":"finance_vat_use_reverse_complete","type":"t","match":" ","target":null,"validated":true,"deferrable":true,"definition":"TRIGGER DEFERRABLE INITIALLY DEFERRED","targetKeys":null,"deleteAction":" ","updateAction":" ","initiallyDeferred":true}]}]}}'::jsonb; e jsonb; actual jsonb; row_oid oid; resolved oid; table_name text; actual_count integer; expected_count integer;
BEGIN
 IF p_schema IS NULL OR p_schema !~ '^[a-z][a-z0-9_]*$' OR p_schema LIKE 'pg_%' OR pg_catalog.current_setting('server_version_num')::integer/10000<>17
  OR pg_catalog.current_setting('session_replication_role')<>'origin' OR (pg_catalog.current_schemas(false))[1] IS DISTINCT FROM p_schema
  OR pg_catalog.array_position(pg_catalog.current_schemas(true),'pg_catalog')>pg_catalog.array_position(pg_catalog.current_schemas(true),p_schema) THEN
