 END LOOP;
 EXECUTE pg_catalog.format('SELECT %I.r1_installation_catalog($1,$2,$2)',p_schema) INTO actual USING p_schema,ARRAY(SELECT value FROM pg_catalog.jsonb_array_elements_text(expected->'tables'));
